[5861] = {"Find Myranda",{{1855}},{{11872}},52,60,nil,nil,{"Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift."},nil,nil,nil,nil,{5848},nil,nil,nil,139},
