[6582] = {"The Test of Skulls, Scryer",{{10321}},{{10321}},55,60,nil,nil,{"You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.$B$BYou know that Scryer can be found in Winterspring."},nil,{nil,nil,{{16869}}},nil,nil,{6570},nil,nil,nil,15},
[6583] = {"The Test of Skulls, Somnus",{{10321}},{{10321}},55,60,nil,nil,{"Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife."},nil,{nil,nil,{{16870}}},nil,nil,{6582},nil,nil,nil,15},
[6584] = {"The Test of Skulls, Chronalis",{{10321}},{{10321}},55,60,nil,nil,{"Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife."},nil,{nil,nil,{{16871}}},nil,nil,{6583},nil,nil,nil,15},
[6585] = {"The Test of Skulls, Axtroz",{{10321}},{{10321}},55,60,nil,nil,{"Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife."},nil,{nil,nil,{{16872}}},nil,nil,{6582,6583,6584},nil,nil,nil,15},
[6601] = {"Ascension...",{{10321}},{{10182}},55,60,nil,nil,{"It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next."},nil,nil,nil,nil,{6585},nil,nil,nil,15},
[6602] = {"Blood of the Black Dragon Champion",{{10182}},{{10182}},55,60,nil,nil,{"Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar."},nil,{nil,nil,{{16663}}},nil,nil,{6601},nil,nil,nil,405},
