[6607] = {"Nat Pagle, Angler Extreme",{{12919}},{{12919}},35,45,nil,nil,{"Nat Pagle wants you to catch the following fish:$B$BMisty Reed Mahi Mahi from the Misty Reed Strand in the Swamp of Sorrows.$B$BA Sar'theris Striker from the Sar'theris Strand in Desolace.$B$BFeralas Ahi from the Verdantis River of Feralas.$B$BSavage Coast Blue Sailfin from the Savage Coast of Stranglethorn Vale.$B$BReturn to Nat Pagle when you have reeled them all in!"},nil,{nil,nil,{{16967},{16968},{16969},{16970}}},nil,nil,{6608,6609},nil,nil,nil,15,{356,225}},
[6608] = {"You Too Good.",{{3332}},{{12919}},35,45,nil,nil,{"You think Lumak is trying to tell you that he can no longer help you improve your fishing skill. You may want to try to find his friend, Nat Pagle, a human fishing off one of the islands south of Theramore (at least that's what you think Lumak said)."},nil,nil,nil,nil,nil,nil,nil,nil,1637,{356,225}},
[6609] = {"I Got Nothin' Left!",{{5161}},{{12919}},35,45,nil,nil,{"Travel to Kalimdor, to the coastal city of Theramore. From there you must search for an island, south of the main town. Nat Pagle awaits your arrival!"},nil,nil,nil,nil,nil,nil,nil,nil,1537,{356,225}},
[6610] = {"Clamlette Surprise",{{8125}},{{8125}},35,45,nil,nil,{"Dirge Quikcleave wants you to get the following items:$B$B12 Giant Eggs. You will find those on the Rocs wandering Tanaris or any other species of large bird.$B$B10 pieces of Zesty Clam Meat. You can find those in clams, naturally!$B$B20 pieces of Alterac Swiss. Get thee to a cheesery!$B$BGather all of the items and return to Dirge."},nil,{nil,nil,{{7974},{8932},{12207}}},nil,nil,{6611,6612},nil,nil,nil,440,{185,225}},
[6611] = {"To Gadgetzan You Go!",{{3399}},{{8125}},35,45,nil,nil,{"Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career."},nil,nil,nil,nil,nil,nil,nil,nil,1637,{185,225}},
