[6621] = {"King of the Foulweald",{{12757}},{{12757}},21,26,nil,nil,{"Place Karang's Banner on the Foulweald Totem Mound.  Do not let the furbolgs destroy the banner.  Defeat Chief Murgut and bring Murgut's Totem to Karang Amakkar at Zoram'gar."},nil,{nil,nil,{{16976}}},nil,nil,{216},nil,nil,nil,331,nil,nil,nil,{16972}},
[6622] = {"Triage",{{12920}},{{12920}},40,45,nil,nil,{"Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.$B$BRemember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged."},nil,nil,nil,nil,{6623},nil,nil,nil,45,{129,225}},
