[7441] = {"Pusillin and the Elder Azj'Tordin",{{14355}},{{14355}},54,58,nil,nil,{"Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.$B$BReturn to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations."},nil,{nil,nil,{{18261}}}},
[7461] = {"The Madness Within",{{14358}},{{14358}},56,60,nil,nil,{"You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.$B$BEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.$B$BReturn to the Shen'dralar Ancient in the courtyard should you complete this quest."},nil,{{{11486},{11496}}}},
[7462] = {"The Treasure of the Shen'dralar",{{14358}},{nil,{179517}},56,60,255,nil,{"Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!"},nil,nil,nil,nil,{7461}},
[7463] = {"Arcane Refreshment",{{14368}},{{14368}},60,60,nil,128,{"Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence."},nil,{nil,nil,{{18299}}}},
