[7564] = {"Wildeyes",{{14436}},{{14437}},60,58,nil,256,{"Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes."},nil,nil,nil,nil,{7563},nil,nil,nil,46},
[7601] = {"What Niby Commands",{{14469}},{{14470}},50,50,nil,256,{"Speak with Impsy in Felwood."},nil,nil,nil,nil,nil,nil,nil,nil,361},
[7602] = {"Flawless Fel Essence",{{14470}},{{14470}},50,55,nil,256,{"Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.$B$BThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.$B$BRecover the Flawless Fel Essences and return  to Impsy in Felwood."},nil,{nil,nil,{{18622},{18623},{18624}}},nil,nil,{7601},nil,nil,nil,361},
[7603] = {"Kroshius' Infernal Core",{{14470}},{{14469}},50,55,nil,256,{"Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.$B$BReturn Kroshius' Infernal Core to Niby the Almighty in Felwood."},nil,{nil,nil,{{18625}}},nil,nil,{7602},nil,nil,nil,361,nil,nil,nil,{18626}},
[7604] = {"A Binding Contract",{nil,nil,{18628}},{{12944}},60,60,nil,nil,{"Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron."},nil,{nil,nil,{{17203}}},nil,nil,nil,nil,nil,nil,1584},
[7621] = {"A Warning",{{14494}},{{14494}},60,60,nil,16,nil,nil,nil,nil,nil,nil,nil,nil,nil,139},
[7622] = {"The Balance of Light and Shadow",{{14494}},{{14494}},60,60,nil,16,{"Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.$B$BYou may view the Death Post to view how many Peasants have been slain."},nil,nil,nil,nil,{7621},nil,nil,nil,139},
[7623] = {"Lord Banehollow",{{14437}},{{9516}},60,58,nil,256,{"Purchase Shadowy Potions from Gorzeeki in the Burning Steppes.$B$BUse the potions to travel through Jaedenar, and speak with Lord Banehollow."},nil,nil,nil,nil,{7564},nil,nil,nil,46},
[7624] = {"Ulathek the Traitor",{{9516}},{{9516}},60,58,nil,256,{"Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar."},nil,{nil,nil,{{18719}}},nil,nil,{7623},nil,nil,nil,148},
[7625] = {"Xorothian Stardust",{{9516}},{{14437}},60,60,nil,256,{"Purchase Xorothian Stardust from Ur'dan.  Bring it to Gorzeeki Wildeyes in the Burning Steppes."},nil,{nil,nil,{{18687}}},nil,nil,{7624},nil,nil,nil,148},
[7626] = {"Bell of Dethmoora",{{14436}},{{14437}},60,60,nil,256,{"Bring 10 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes."},nil,{nil,nil,{{9264}}},nil,nil,{7564},nil,nil,nil,46},
[7627] = {"Wheel of the Black March",{{14436}},{{14437}},60,60,nil,256,{"Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes."},nil,{nil,nil,{{11370},{14344}}},nil,nil,{7564},nil,nil,nil,46},
[7628] = {"Doomsday Candle",{{14436}},{{14437}},60,60,nil,256,{"Bring 35 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes."},nil,{nil,nil,{{15416}}},nil,nil,{7564},nil,nil,nil,46},
