[7631] = {"Dreadsteed of Xoroth",{{14436}},{{14504}},60,60,nil,256,{"Read Mor'zul's Instructions.  Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you."},nil,nil,nil,nil,{7629},nil,nil,nil,46},
[7632] = {"The Ancient Leaf",{nil,nil,{18703}},{{14524}},60,60,nil,4,{"Find the owner of the Ancient Petrified Leaf. Good luck, $N; It's a big world."}},
[7633] = {"An Introduction",{{14524}},{{14524}},60,60,nil,4,nil,nil,nil,nil,nil,{7632}},
[7634] = {"Ancient Sinew Wrapped Lamina",{{14526}},{{14526}},60,60,nil,4,{"Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood."},nil,{nil,nil,{{18704}}},nil,nil,{7633}},
[7635] = {"A Proper String",{{14525}},{{14525}},60,60,nil,4,{"Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood."},nil,{nil,nil,{{18705}}},nil,nil,{7633}},
[7636] = {"Stave of the Ancients",{{14524}},{{14524}},60,60,nil,4,{"You must find and destroy these four demonic corrupters:$B$BSimone the Seductress.$B$BKlinfran the Crazed.$B$BSolenor the Slayer.$B$BArtorius the Doombringer.$B$BDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.$B$BRefer to the Petrified Bark in your inventory for clues as to their whereabouts.$B$BYou MUST complete this task by yourself."},nil,{{{14530},{14533},{14534},{14535}}},nil,nil,{7633}},
[7637] = {"Emphasis on Sacrifice",{{928}},{{11406}},60,60,nil,2,{"Travel to Ironforge and get High Priest Rohan's Exorcism Censer.  You will need to make a donation of 150 gold in order to secure it."},nil,nil,nil,nil,nil,nil,nil,nil,1519},
[7638] = {"Lord Grayson Shadowbreaker",{{6171}},{{928}},60,60,nil,2,{"Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."},nil,nil,nil,nil,nil,nil,nil,{7638,7670},1519},
[7639] = {"To Show Due Judgment",{{11406}},{{928}},60,60,nil,2,{"Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."},nil,nil,nil,nil,{7637},nil,nil,nil,1537},
[7640] = {"Exorcising Terrordale",{{928}},{{928}},60,60,nil,2,{"Use the Exorcism Censer to drive out the spirits that torment Terrordale.  When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."},nil,{{{14564}}},nil,nil,{7639},nil,nil,nil,1519,nil,nil,nil,{18752}},
[7641] = {"The Work of Grimand Elmore",{{928}},{{1416}},60,60,nil,2,{"Speak with Grimand Elmore in Stormwind's Dwarven District."},nil,nil,nil,nil,nil,nil,nil,nil,1519},
[7642] = {"Collection of Goods",{{1416}},{{1416}},60,60,nil,2,{"Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind."},nil,{nil,nil,{{8836},{12360},{13180},{14047}}},nil,nil,{7641},nil,nil,nil,1519},
[7643] = {"Ancient Equine Spirit",{{928}},{{14566}},60,60,nil,2,{"Acquire special horse feed used for feeding a spirit horse.  Merideth Carlson in Southshore apparently is the source for such food.$B$BTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood.  Doing so will free the Ancient Equine Spirit.  Feed it the special horse feed, thereby soothing the spirit.  Finally, give it the Arcanite Barding so it may bless it."},nil,{nil,nil,{{18775}}},nil,nil,nil,nil,nil,nil,1519},
[7644] = {"Blessed Arcanite Barding",{{14566}},{{928}},60,60,nil,2,{"Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."},nil,nil,nil,nil,{7643},nil,nil,nil,1519},
[7645] = {"Manna-Enriched Horse Feed",{{2357}},{{2357}},60,60,nil,2,{"Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills.  The Argent Dawn is known as the sole purveyor of the biscuits.$B$BYou also need to give her 50 gold to soothe her ruffled sensibilities."},nil,{nil,nil,{{13724}}},nil,nil,{7643},nil,nil,nil,267},
[7646] = {"The Divination Scryer",{{928}},{{928}},60,60,nil,2,{"Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."},nil,{nil,nil,{{12800},{18335}}},nil,nil,{7644},nil,nil,nil,1519},
[7647] = {"Judgment and Redemption",{{928}},{{14568}},60,60,nil,2,{"Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth the spirits you must judge.  Defeating these spirits will summon forth Death Knight Darkreaver.  Defeat him and reclaim the lost soul of the fallen charger.$B$BGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger."},nil,{nil,nil,{{18746},{18749},{18792},{18799}}},nil,nil,{7646},nil,nil,nil,1519,nil,nil,nil,{18746,18749}},
[7648] = {"Grimand's Finest Work",{{1416}},{{928}},60,60,nil,2,{"Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection."},nil,nil,nil,nil,{7642},nil,nil,nil,1519},
