[7701] = {"WANTED: Overseer Maltorius",{nil,{179827}},{{14634}},45,50,nil,nil,{"Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.$B$BSlay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward."},nil,{nil,nil,{{18946}}},nil,nil,nil,nil,nil,nil,51},
[7703] = {"Unfinished Gordok Business",{{14325}},{{14325}},56,60,nil,nil,{"Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.$B$BAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings."},nil,{nil,nil,{{18336}}}},
[7704] = {"Look at the Size of It!",{nil,nil,{18950}},nil,45,50,nil,nil,{"Take Chambermaid Pillaclencher's Pillow to Evonice Sootsmoker in the Searing Gorge."}},
[7721] = {"Fuel for the Zapping",{{14637}},{{14637}},45,48,nil,nil,{"Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there."},nil,{nil,nil,{{18958}}},nil,nil,nil,nil,nil,nil,357},
[7722] = {"What the Flux?",{{14624}},{{14624}},45,50,nil,nil,{"Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge."},nil,{nil,nil,{{18922}}},nil,nil,nil,nil,nil,nil,51},
[7723] = {"Curse These Fat Fingers",{{14627}},{{14627}},45,49,nil,nil,{"Hansel Heavyhands wants you to kill 20 Heavy War Golems.$B$BThe Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge."},nil,{{{5854}}},nil,nil,nil,nil,nil,nil,51},
[7724] = {"Fiery Menace!",{{14627}},{{14627}},45,49,nil,nil,{"Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.$B$BReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders."},nil,{{{5858}}},nil,nil,nil,nil,nil,nil,51},
[7725] = {"Again With the Zapped Giants",{{14637}},{{14637}},45,55,nil,nil,{"Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form.  Bring 10 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas."},nil,{nil,nil,{{18956}}},nil,nil,{7003},nil,nil,nil,357,nil,nil,nil,{18904}},
[7726] = {"Refuel for the Zapping",{{14637}},{{14637}},45,55,nil,nil,{"Collect 6 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there."},nil,{nil,nil,{{18958}}},nil,nil,{7721},nil,nil,nil,357},
[7727] = {"Incendosaurs? Whateverosaur is More Like It",{{14627}},{{14627}},45,49,nil,nil,{"Hansel Heavyhands wants you to kill 20 Incendosaurs.$B$BYou will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.$B$BReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs."},nil,{{{9318}}},nil,nil,nil,nil,nil,nil,51},
[7728] = {"STOLEN: Smithing Tuyere and Lookout's Spyglass",{nil,{179827}},{{14626}},45,48,nil,nil,{"Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.$B$BThe only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts. "},nil,{nil,nil,{{18959},{18960}}},nil,nil,nil,nil,nil,nil,51},
[7729] = {"JOB OPPORTUNITY: Culling the Competition",{nil,{179827}},{{14626}},45,48,nil,nil,{"Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task."},nil,{{{5844},{5846}}},nil,nil,nil,nil,nil,nil,51},
[7730] = {"Zukk'ash Infestation",{{7875}},{{7875}},39,45,nil,nil,{"Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas."},nil,{nil,nil,{{18961}}},nil,nil,{2903},nil,nil,nil,357},
[7731] = {"Stinglasher",{{7875}},{{7875}},39,47,nil,nil,{"Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas."},nil,{nil,nil,{{18962}}},nil,nil,{2903},nil,nil,nil,357},
[7732] = {"Zukk'ash Report",{{7875}},{{7010}},39,48,nil,nil,{"Deliver the Camp Mojache Zukk'ash Report to Zilzibin Drumlore.  He resides in the Drag of Orgrimmar."},nil,nil,nil,nil,{7730,7731},nil,nil,nil,357},
[7733] = {"Improved Quality",{{7852}},{{7852}},40,48,nil,nil,{"Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas."},nil,{nil,nil,{{18947}}},nil,nil,{2821},nil,nil,nil,357},
[7734] = {"Improved Quality",{{7854}},{{7854}},40,48,nil,nil,{"Bring 10 Rage Scar Yeti Hides to Jangdor Swiftstrider at Camp Mojache, Feralas."},nil,{nil,nil,{{18947}}},nil,nil,{2822},nil,nil,nil,357},
[7735] = {"Pristine Yeti Hide",{nil,nil,{18969}},{{7852}},40,48,nil,nil,{"Bring the Pristine Yeti Hide to Pratt McGrubben at the Feathermoon Stronghold, Feralas."},nil,nil,nil,nil,nil,nil,nil,nil,357},
