[7738] = {"Perfect Yeti Hide",{nil,nil,{18972}},{{7854}},40,48,nil,nil,{"Bring the Perfect Yeti Hide to Jangdor Swiftstrider at Camp Mojache, Feralas."},nil,nil,nil,nil,nil,nil,nil,nil,357},
[7761] = {"Blackhand's Command",{nil,nil,{18987}},{nil,{179880}},55,60,nil,nil,{"That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.$B$BThe letter indicates that General Drakkisath guards the brand. Perhaps you should investigate."}},
[7781] = {"The Lord of Blackrock",{nil,nil,{19003}},{{1748}},60,60,nil,nil,{"Return the Head of Nefarian to Highlord Bolvar Fordragon in Stormwind."},nil,nil,nil,nil,nil,nil,nil,nil,1519},
[7782] = {"The Lord of Blackrock",{{1748}},{{14721}},60,60,nil,nil,{"Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Afrasiabi."},nil,nil,nil,nil,{7781},nil,nil,nil,1519},
[7783] = {"The Lord of Blackrock",{nil,nil,{19002}},{{4949}},60,60,nil,nil,{"Return the Head of Nefarian to Thrall in Orgrimmar."},nil,nil,nil,nil,nil,nil,nil,nil,1637},
[7784] = {"The Lord of Blackrock",{{4949}},{{14720}},60,60,nil,nil,{"Speak with High Overlord Saurfang in Orgrimmar. He stands waiting for you in the Valley of Strength."},nil,nil,nil,nil,{7783},nil,nil,nil,1637},
[7785] = {"Examine the Vessel",{nil,nil,{19016}},{{14347}},60,60,nil,nil,{"Examine the Vessel of Rebirth and return it to Highlord Demitrian."},nil,nil,nil,nil,nil,nil,nil,nil,357},
[7786] = {"Thunderaan the Windseeker",{{14347}},{{14347}},60,60,nil,nil,{"To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Windseeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian in Silithus."},nil,{nil,nil,{{17771},{18563},{18564},{19017}}},nil,nil,{7785},nil,nil,nil,357},
[7787] = {"Rise, Thunderfury!",{nil,nil,{19018}},{{14347}},60,60,nil,nil,{"Present the Dormant Wind Kissed Blade to Highlord Demitrian."},nil,nil,nil,nil,{7786},nil,nil,nil,357},
