[7828] = {"Stalking the Stalkers",{{14741}},{{14741}},44,48,nil,nil,{"Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 15 Silvermane Stalkers and 15 Silvermane Howlers. Return to him once the task is complete.$B$BMarkhor mentioned that the wolves hide in the wilds of the Hinterlands."},nil,{{{2925},{2926}}},nil,nil,nil,nil,nil,nil,47},
[7829] = {"Hunt the Savages",{{14741}},{{14741}},44,48,nil,nil,{"Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 20 Savage Owlbeasts. Return to him once the task is complete.$B$BMarkhor mentioned that the Savage Owlbeasts occupy the wilds of the Hinterlands."},nil,{{{2929}}},nil,nil,nil,nil,nil,nil,47},
[7830] = {"Avenging the Fallen",{{14741}},{{14741}},44,48,nil,nil,{"Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete.$B$BMarkhor mentioned that the Razorbeak Skylord are a rare breed that tend to occupy the wilds of the Hinterlands."},nil,{nil,nil,{{19025}}},nil,nil,nil,nil,nil,nil,47},
