[8497] = {"Desert Survival Kits",{nil,nil,{20807}},{{15174}},60,60,nil,nil,{"Bring 4 Globes of Water, 4 Powerful Anti-Venom and 4 Smoked Desert Dumplings to Calandrath at the inn in Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing I in order to complete this quest."},nil,{nil,nil,{{7079},{19440},{20452}}}},
[8498] = {"Twilight Battle Orders",{nil,nil,{20943}},{{15181}},60,60,nil,nil,{"Obtain the Twilight Battle Orders and bring them Commander Mar'alith at Cenarion Hold in Silithus.  You must also bring Tactical Task Briefing X in order to complete this quest."},nil,{nil,nil,{{20803}}}},
[8501] = {"Target: Hive'Ashi Stingers",{nil,nil,{20941}},{{15181}},60,60,nil,nil,{"Kill 30 Hive'Ashi Stingers and report back to Commander Mar'alith at Cenarion Hold in Silithus.  You must also bring Combat Task Briefing XII in order to complete this quest."},nil,{{{11698}}}},
[8502] = {"Target: Hive'Ashi Workers",{nil,nil,{20942}},{{15181}},60,60,nil,nil,{"Slay 30 Hive'Ashi Workers and report back to Commander Mar'alith at Cenarion Hold in Silithus.  You must also bring Combat Task Briefing III in order to complete this quest."},nil,{{{11721}}}},
[8507] = {"Field Duty",{{15540}},{{15540}},60,60,77,nil,{"Report for duty at the Ironforge Brigade post near Hive'Zora.  Prepare your Unsigned Field Duty Papers and obtain Signed Field Duty Papers from Captain Blackanvil and return to Windcaller Kaldon at Cenarion Hold in Silithus.$B$BNote: Healing or casting beneficial spells on a member of the Ironforge Brigade will flag you for PvP."},nil,{nil,nil,{{20810}}}},
