[8733] = {"Eranikus, Tyrant of the Dream",{{15362}},{{15624}},60,60,nil,nil,{"Travel to the continent of Teldrassil and find Malfurion's agent somewhere outside the walls of Darnassus."},nil,nil,nil,nil,{8555},nil,nil,nil,141},
[8734] = {"Tyrande and Remulos",{{15624}},{{11832}},60,60,nil,nil,{"Travel to the Moonglade and speak to Keeper Remulos. "},nil,nil,nil,nil,{8733},nil,nil,nil,141},
[8735] = {"The Nightmare's Corruption",{{11832}},{{11832}},60,60,nil,nil,{"Travel to the four Emerald Dream portals in Azeroth and collect a Fragment of the Nightmare's Corruption from each. Return to Keeper Remulos in the Moonglade when you have completed this task."},nil,{nil,nil,{{21146},{21147},{21148},{21149}}},nil,nil,{8734},nil,nil,nil,493},
[8736] = {"The Nightmare Manifests",{{11832}},{{11832}},60,60,nil,nil,{"Defend Nighthaven from Eranikus. Do not let Keeper Remulos perish. Do not slay Eranikus. Defend yourself. Await Tyrande."},nil,nil,nil,nil,{8735},nil,nil,nil,493},
[8737] = {"Azure Templar",{nil,nil,{21245}},{{15306}},60,60,nil,nil,{"Summon and slay an Azure Templar and report back to Bor Wildmane in Cenarion Hold.  You must also bring Tactical Task Briefing I in order to complete this quest."},nil,{{{15211}}}},
[8738] = {"Hive'Regal Scout Report",{nil,nil,{21166}},{{15191}},60,60,nil,nil,{"Contact Cenarion Scout Landion inside Hive'Regal and return the Hive'Regal Scout Report to Windcaller Proudhorn at Cenarion Hold.  You must also bring Tactical Task Briefing VII in order to complete this quest."},nil,{nil,nil,{{21160}}}},
