[31001] = {"Respects For The Fallen",{{14392}},{{14392}},56,57,178,nil,{"Warlord Runthak in Orgrimmar wants you to pay respects to a Horde veteran warrior lost in Eastern Winterspring.\n\nThe location and the true story are a mystery, try to look for any clues - a camp he might have set, a shelter protected from the elements he might have rested in or a sight of a fierce battle."},nil,nil,nil,nil,nil,nil,nil,nil,14,nil,nil,nil,{90077}},
[31002] = {"Respects For The Fallen",{{12480}},{{12480}},58,60,77,nil,{"Melris Malagan in Stormwind wants you to pay respects to a group of soldiers who were lost in Eastern Winterspring."},nil,nil,nil,nil,nil,nil,nil,nil,1519,nil,nil,nil,{90078},31007},
[31003] = {"Food For The Soul",{nil,{5000075}},{{8125}},58,60,nil,nil,{"Consult an expert in cooking, perhaps Dirge Quickcleave from Gadgetzan can help?|cFF42E8F3\n\nGo up the mountain through Azure Rest to reach this journal!|r"},nil,nil,nil,nil,nil,nil,nil,nil,618,{185,300},nil,nil,nil,31004},
[31004] = {"Food For The Soul",{{8125}},{{8125}},58,60,nil,nil,{"Dirge Quickcleave in Gadgetzan doubted our ability to collect the ingredients for Honey Butter Bread.\n\n-Many vendors on Azeroth sell Freshly Baked Bread, that would be the easiest way to get it.\n\n-Honey can be found on some of the wasps in Un'Goro.\n\n-Butter can be bought in Hillsbrad Foothills. Either Tarren Mill or Southshore."},nil,{nil,nil,{{4541},{90073},{90074}}},nil,nil,{31003},nil,nil,nil,440,nil,nil,nil,nil,31005},
[31005] = {"Food For The Soul",{{8125}},{{8125}},58,60,nil,nil,{"Speak with Dirge and wait for him to finish cooking Honey Butter Bread."},nil,nil,nil,nil,{31004},nil,nil,nil,440},
