[31012] = {"The Problem at Hand",{{90073}},{{90073}},60,60,nil,nil,{"The Fulborg from Azure Rest wants us to make the area a bit less hostile by getting rid of Spirestone Brutes and Spirestone Channelers."},nil,{{{90080},{90081}}},nil,nil,{31010},nil,nil,nil,618,nil,nil,nil,nil,31013},
[31013] = {"A Moment of Respite",{{90073}},{{90073}},60,60,nil,nil,{"Speak with the furbolg and hear his story in Azure Rest."},nil,{{{90073}}},nil,nil,{31012},nil,nil,nil,618,nil,nil,nil,nil,31014},
[31014] = {"Dire Guidance",{{90073}},{{10929}},60,60,nil,nil,{"Seek counsel of the blue dragonflight. The Caverns of Mazthoril serve as home for them on Kalimdor. The guardians will surely attack invaders on sight, but perhaps their reclusive matron protectorate will be willing to assist us?"},nil,nil,nil,nil,{31013},nil,nil,nil,618,nil,nil,nil,nil,31015},
[31015] = {"Dark Price of Necessity",{{10929}},{{10929}},60,60,nil,nil,{"Haleh in Mazthoril has tasked you with killing Vectus in the School of Necromancy and recovering his scepter."},nil,{{{10432}}},nil,nil,{31014},nil,nil,nil,618,nil,nil,nil,nil,31016},
[31016] = {"A Light Task",{{10929}},{{11034}},60,60,nil,nil,{"Our task is to find a powerful paladin, the best bet would probably be Light's Hope Chapel. Perhaps we can ask the leader of the Argent Dawn, Lord Maxwell Tyrosus for help."},nil,nil,nil,nil,{31015},nil,nil,nil,618,nil,nil,nil,nil,31017},
[31017] = {"Requirements for the Ritual",{{11034}},{{11034}},60,60,nil,nil,{"Lord Maxwell Tyrosus in Light's Hope Chapel needs several materials to purify the scepter:\n- A bottle of Holy Water from Stratholme.\n- One bar of Arcanite from a knowledgeable Alchemist or Miner.\n- Three Sacred Candles, available for purchase at a reagent vendor.\n- Three piles of Soul Dust from an enchanter.\n- One Symbol of Divinity, also available at a reagent vendor."},nil,{nil,nil,{{13180},{12360},{11083},{17029},{17033}}},nil,nil,{31016},nil,nil,nil,139,nil,nil,nil,nil,31018},
[31018] = {"Holy Concentration",{{11034}},{{11034}},60,60,nil,nil,{"Wait for the purification ritual to be complete."},nil,nil,nil,nil,{31017},nil,nil,nil,139,nil,nil,nil,nil,31019},
[31019] = {"A Journey Back",{{11034}},{{90073}},60,60,nil,nil,{"With the scepter purified we can return to Winterspring. Talruk in Azure Rest will be waiting for us."},nil,nil,nil,nil,{31018},nil,nil,nil,139,nil,nil,nil,nil,31020},
[31020] = {"Arcane Blight",{{90073}},{{90073}},60,60,nil,nil,{"Use the scepter on the skull in Azure Rest and speak with the dragon's spirit."},nil,{nil,{{5000076}},{{90082}}},nil,nil,{31019},nil,nil,nil,618,nil,nil,nil,nil,31021},
[31021] = {"Arcane Blight",{{90074}},{{90074}},60,60,nil,nil,{"Speak with Veligos in Azure Rest. Find out his story and consult on the next steps."},nil,{nil,nil,{{90074}}},nil,nil,{31020},nil,nil,nil,618,nil,nil,nil,nil,31022},
[31022] = {"Arcane Blight",{{90074}},{{90074}},60,60,nil,nil,{"Veligos asked us to fight our way into the depths of the Azure Rest cave and kill the ogres that are empowering the crystal. "},nil,{{{90082}}},nil,nil,{31021},nil,nil,nil,618,nil,nil,nil,nil,31023},
[31023] = {"Arcane Blight",{{90074}},{{90074}},60,60,nil,nil,{"Speak with Veligos when you are ready to start the summoning. He wants us to kill the Spirestone Magus Lord at the crystal in Azure Rest."},nil,{{{90088}},nil,{{90074}}},nil,nil,{31022},nil,nil,nil,618,nil,nil,nil,nil,31024},
[31024] = {"Arcane Blight",{{90074}},{{90074}},60,60,nil,nil,{"Veligos from Azure Rest wants us to go into the depths of Lower Blackrock Spire to summon and kill the true leader of Spirestone clan - Urok Doomhowl and recover the second part of his control orb."},nil,{{{10584}}},nil,nil,{31023},nil,nil,nil,618,nil,nil,nil,nil,31025},
[31025] = {"Arcane Blight",{{90074}},{{90074}},60,60,nil,nil,{"Veligos from Azure Rest requires several reagents to conjure magical wards that will suppress the blight:\n\n- Lumenstone, an anti-magic metal can be found in Deadwind Pass near the tower of Kharazan.\n- Four pieces of Guardian Stone from Stone Guardians in Un'Goro Crater.\n- Two Rugged Hide from a skilled Leatherworker.\n- Two pieces of Mooncloth from a Tailor.\n- Two Potions of Anti-Magic from an Alchemist."},nil,{nil,nil,{{12809},{15407},{14342},{61996},{90085}}},nil,nil,{31024},nil,nil,nil,618,nil,nil,nil,nil,31026},
[31026] = {"Arcane Blight",{{90074}},{{90074}},60,60,nil,nil,{"Wait for Veligos to finish casting the conjuration spell."},nil,{nil,nil,{{90074}}},nil,nil,{31025},nil,nil,nil,618,nil,nil,nil,nil,31027},
[31027] = {"Arcane Blight",{{90074}},{{90074}},60,60,nil,nil,{"Begin the purification of Azure Rest in Winterspring. Place the four suppressive wards on each spot of land affected by the arcane blight."},nil,{nil,{{500078}}},nil,nil,{31026},nil,nil,nil,618,nil,nil,nil,{90088},31028},
[31028] = {"Arcane Blight",{{90074}},{{90074}},60,60,nil,nil,{"It is time to put an end to this. Hold Veligos's orb at the crystal in Azure Rest and begin the suppression."},nil,{nil,{{500078}}},nil,nil,{31027},nil,nil,nil,618,nil,nil,nil,{90086},31029},
[31029] = {"Arcane Blight",{{90074}},{{90073}},60,60,nil,nil,{"Speak with Veligos to destroy the Scepter of Vectus and free his spirit. After that we should let Talruk know about everything that has transpired. He can be found in Azure Rest, in Winterspring."},nil,{nil,nil,{{90074}}},nil,nil,{31028},nil,nil,nil,618,nil,nil,nil,nil,31030},
[31030] = {"Arcane Blight",{{90074}},{{10929}},60,60,nil,nil,{"Bring Veligos's Memento to the Matron Protectorate Haleh. She can be found above Mazthorhil in Winterspring."},nil,nil,nil,nil,{31029},nil,nil,nil,618,nil,nil,nil,nil,31031},
[31031] = {"Arcane Blight",{{10929}},{{4949}},60,60,178,nil,{"Return to Orgrimmar and inform Thrall of your success."},nil,nil,nil,nil,{31029},nil,nil,nil,618},
[31032] = {"Arcane Blight",{{10929}},{{2784}},60,60,77,nil,{"Return to Ironforge and inform King Magni Bronzbeard of your success."},nil,nil,nil,nil,{31029},nil,nil,nil,618},
[31033] = {"An Unfortunate Roadblock",{nil,nil,{90090}},{{90083}},58,60,nil,nil,{"Search Deadwind Pass for someone who might know about the demons."},nil,nil,nil,nil,nil,nil,nil,nil,41,nil,nil,nil,nil,31034},
[31034] = {"Help to Recieve Help",{nil,nil,{90083}},{{90083}},58,60,nil,nil,{"The stranger from Deadwind Pass is likely our best choice at finding Lumenstone that the demons took. We will need to bring him a food that buffs mana recovery and some alcohol."},nil,{nil,nil,{{13931},{21151}}},nil,nil,{31033},nil,nil,nil,41,nil,nil,nil,nil,31035},
